__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"PREVIEW_VIDEOS",{enumerable:!0,get:function(){return t}}),Object.defineProperty(e,"AREA_GUIDE",{enumerable:!0,get:function(){return o}});const t={},o={'Low back':{hook:'Most back pain is not damage. It is an irritated back and a body that stopped moving well.',usually:["Usually nothing is broken or damaged. Lots of people have \"bad\" looking scans and feel totally fine","You did more than your back was ready for, like a big lifting day, long hours sitting, bad sleep or a stressful stretch","A pinched or cranky nerve, if the pain shoots down your leg past the knee","Your hips and core stopped doing their part, so your back picks up the slack"],plan:[['Visit 1','Find what is driving it, treat it hands on with manipulation or dry needling, and give you 3 or 4 moves that calm it down'],['Weeks 2 to 6','Build hip and trunk strength, then load the movements that hurt, like bending and lifting'],['After that','Back to the gym, golf or work without guarding it, with a plan to keep it that way']],timeline:'Most people feel a real change in 2 to 3 weeks',today:{name:'Band pull through',dose:'2 x 12',how:"Anchor a band low behind you, hold it between your legs and face away. Push your hips back, then drive them forward and stand tall. Teaches your hips to lift so your back does not have to."}},Neck:{hook:'Most neck pain comes from a stiff upper back, long days at a screen, and muscles that are working too hard.',usually:["A stiff neck and upper back that make it hard to turn your head","Small neck muscles that get tired, so the bigger ones tighten up. Common after a car accident or long days at a desk","Headaches that actually start in your neck","A cranky nerve, if pain or tingling runs down your arm"],plan:[['Visit 1','Screen out anything serious, then hands on work and dry needling to get you moving'],['Weeks 2 to 6','Deep neck and shoulder blade strength, and setting up your desk and sleep'],['After that','Fewer flare ups and a short routine you can do anywhere']],timeline:'Usually improving within 1 to 3 weeks',today:{name:'Thread the needle',dose:'6 each side',how:"On hands and knees, slide one arm under your body and rotate, then open it toward the ceiling. Exhale into the reach. Frees up the upper back so your neck stops doing the work."}},Shoulder:{hook:'Shoulders usually hurt because the tendons are overloaded or the shoulder blade is not doing its job.',usually:["The shoulder tendons got more work than they were ready for. Usually not a tear, and plenty of people have tears with no pain at all","A frozen shoulder that slowly gets stiff and painful, most common between 40 and 60","A shoulder that feels loose or like it slips out","Pain that is actually coming from your neck"],plan:[['Visit 1','Pin down which tendon or structure it is, settle the pain, and start loading it the right amount'],['Weeks 2 to 8','Progress cuff and shoulder blade strength week by week. Too little does nothing, too much flares it'],['After that','Pressing, throwing and lifting overhead again']],timeline:'Tendons adapt slowly. Expect 6 to 12 weeks for lasting change',today:{name:'Bottoms up kettlebell hold',dose:'3 x 20 sec each arm',how:"Hold a light kettlebell upside down by the handle at shoulder height, elbow bent. Squeeze and keep it balanced. Wakes up the cuff without irritating it."}},Hip:{hook:'Hip pain is often a strength and control problem we can measure and close.',usually:["Sore tendons on the outside of the hip. It hurts to lie on that side or walk up stairs","A pinch in the front of the hip when you squat deep or sit a long time","Wear and tear in the hip, which gets a lot better with the right strength work","Pain that is actually coming from your low back"],plan:[['Visit 1','Test strength and range side to side, treat what is tight, and start the right loading'],['Weeks 2 to 6','Progressive glute and hip strength, plus how you squat, step and run'],['After that','Running, lifting and sleeping without that ache']],timeline:'Most people notice a change in 3 to 4 weeks',today:{name:'90/90 hip switches',dose:'2 x 8 each side',how:"Sit with both knees bent to 90 degrees, one in front and one to the side. Rotate both knees to the other side and back, staying tall. Use your hands behind you if needed."}},Knee:{hook:'Knees almost always get better with the right load, built up week by week.',usually:["Pain around the kneecap when you ramp up activity faster than your legs can handle","A sore tendon just below the kneecap from running or jumping a lot","Wear and tear (arthritis), where exercise is the first thing that helps, often as much as a shot","Cartilage changes that look scary on an MRI but usually get better with strength work, not surgery"],plan:[['Visit 1','Find the cause and the movements that hurt, and calm it down with load you can tolerate'],['Weeks 2 to 8','Quad and hip strength that ramps up each week, with clear tests to move forward'],['After that','Stairs, squats, running and sport, with a plan to stay there']],timeline:'Expect real progress in 4 to 8 weeks',today:{name:'Spanish squat',dose:'4 x 30 sec hold',how:"Loop a heavy band behind your knees and anchor it in front of you. Sit back into a squat with shins vertical. Loads the quads hard while taking stress off the front of the knee."}},'Ankle or foot':{hook:'Ankles and feet need tendon loading, balance, and a smart return to running.',usually:["Heel pain that is worst with your first steps in the morning","A sore Achilles after you picked up your running or jumping too fast","An old sprain that never fully healed, so your ankle keeps rolling","Weak calves and shaky balance that leave your feet doing too much"],plan:[['Visit 1','Assess the foot and ankle, treat what is irritated, and start tendon loading'],['Weeks 2 to 8','Calf strength, balance and hopping progressions'],['After that','A return to running or sport that does not set you back']],timeline:'Tendons take time. Plan on 6 to 12 weeks',today:{name:'Wall tibialis raises',dose:'2 x 15',how:"Lean your back against a wall with heels a foot out. Lift your toes and forefoot toward your shins, then lower slowly. Builds the muscle runners always forget."}},'After surgery':{hook:'After surgery, the right plan follows your surgeon\u2019s protocol and gets you further than the protocol alone.',usually:["Swelling and pain that make your muscles shut off, especially your thigh after knee surgery","Stiffness that sets in if you do not get moving early, in the way your surgeon allows","One side much weaker than the other, which raises the chance of getting hurt again","Going back to sports because enough time passed, not because you passed real strength tests"],plan:[['Visit 1','Review your protocol and restrictions, and set the plan with clear goals for each stage'],['Each stage','Restore motion, then strength, then the activities that matter to you'],['Return','Testable criteria for getting back to sport or full activity, not just the calendar']],timeline:'Follows your surgeon\u2019s timeline. Usually 3 to 9 months',today:{name:'Train the other side',dose:'Your usual sets on the non surgical side',how:"Strength training your healthy limb keeps strength in the surgical side through cross education. Get your surgeon's OK, then train the good side normally."}},'Sport performance':{hook:'Performance starts with how you move. Most athletes are leaving strength and speed on the table.',usually:["Ramping up training too fast, one of the biggest causes of overuse injuries","One side stronger or more powerful than the other","Tight spots that make your body cheat on movements","An old injury that was never fully rehabbed. Your last injury is the best predictor of your next one"],plan:[['Visit 1','A full movement and strength screen with numbers, not guesses'],['Weeks 2 to 8','A program that fits your sport and training schedule, adjusted every week'],['Ongoing','Retesting so you see what improved, plus tune ups when something flares']],timeline:'Measurable gains in 4 to 6 weeks',today:{name:'Hip airplanes',dose:'2 x 5 each side, slow',how:"Stand on one leg in a hinge, then rotate your pelvis open toward the ceiling and back closed. Hold a wall at first. Builds hip control most athletes are missing."}}}},898,[]);
